import threading
from functools import partial
from playwright.sync_api import sync_playwright,expect
from voyage_browser import ROOT,Quiet,Server

def main():
 server=Server(('127.0.0.1',0),partial(Quiet,directory=str(ROOT)));threading.Thread(target=server.serve_forever,daemon=True).start()
 try:
  with sync_playwright() as p:
   browser=p.chromium.launch();page=browser.new_page(viewport={'width':1000,'height':900},service_workers='block');errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
   page.goto(f'http://127.0.0.1:{server.server_port}/tests/sheets-harness.html');page.evaluate("""async()=>{await import('/src/planning-controls.js');localStorage.setItem('astralis:gi:objectives-v2',JSON.stringify({targets:[{name:'Contrôle',currentC:2,targetC:4,copies:7}],income:{start:'2026-11-04',end:'2026-12-16'}}));localStorage.setItem('astralis:gi:wish-plan',JSON.stringify({currentPrimos:100000}));const el=document.createElement('wish-objectives');el.dataset.items=JSON.stringify([{name:'Furina',kind:'character',image:'/assets/ui/game-genshin.png'},{name:'Clé de Khaj-Nisut',kind:'weapon',image:'/assets/genshin/weapons/types/sword.png'}]);document.body.append(el);}""")
   expect(page.locator('[data-field=copies]')).to_have_value('2');expect(page.locator('.wish-target-summary')).to_contain_text('2 copie(s)');expect(page.locator('.wish-target-progress-line')).to_contain_text('C2 → C4');assert float(page.locator('.wish-target-progress-line progress').get_attribute('value'))==60;expect(page.locator('[data-wish-target-artwork="0"]')).to_contain_text('Aucune correspondance');expect(page.locator('.wish-income-curve svg')).to_be_visible();expect(page.locator('.wish-income-curve')).to_contain_text('TRAJECTOIRE DU BUDGET');expect(page.locator('[data-wish-funding-target="0"]')).to_contain_text('Finançable dès le 4 nov. 2026')
   name=page.locator('[data-field=name]');name.fill('Furina');expect(page.locator('[data-wish-target-artwork="0"] img')).to_have_attribute('src','/assets/ui/game-genshin.png');expect(page.locator('[data-wish-target-artwork="0"]')).to_contain_text('Personnage trouvé')
   page.locator('[data-field=copies]').fill('3');page.locator('[data-field=copies]').press('Tab');expect(page.locator('[data-field=targetC]')).to_have_value('5');expect(page.locator('.wish-target-summary')).to_contain_text('3 copie(s)')
   page.locator('.goal-ownership summary').click();page.locator('[data-field=targetC]').fill('6');page.locator('[data-field=targetC]').press('Tab');expect(page.locator('[data-field=copies]')).to_have_value('4')
   page.reload();page.evaluate("async()=>{await import('/src/planning-controls.js');const el=document.createElement('wish-objectives');el.dataset.items=JSON.stringify([{name:'Furina',kind:'character',image:'/assets/ui/game-genshin.png'},{name:'Clé de Khaj-Nisut',kind:'weapon',image:'/assets/genshin/weapons/types/sword.png'}]);document.body.replaceChildren(el)}");expect(page.locator('[data-field=copies]')).to_have_value('4');assert not errors,errors
   page.locator('[data-apply-theory]').click();expect(page.locator('[data-theory-status]')).to_have_attribute('data-stale','false')
   before=page.locator('.wish-order-graph figcaption').last.inner_text();curve_before=page.locator('.wish-income-curve>header b').inner_text();field=page.locator('[data-income=extraPrimos]');field.fill('3200');field.press('Tab');expect(page.locator('[data-theory-status]')).to_have_attribute('data-stale','true');assert page.locator('.wish-order-graph figcaption').last.inner_text()==before;assert page.locator('.wish-income-curve>header b').inner_text()!=curve_before
   page.locator('[data-apply-theory]').click();expect(page.locator('[data-theory-status]')).to_have_attribute('data-stale','false');assert page.locator('.wish-order-graph figcaption').last.inner_text()!=before;expect(page.locator('.wish-income-curve svg circle').first).to_be_visible()
   page.locator('[data-income=end]').fill('2020-01-01');page.locator('[data-income=end]').press('Tab');expect(page.locator('[data-apply-theory]')).to_be_disabled();expect(page.locator('.wish-income-curve-empty')).to_be_visible()
   page.locator('[data-field=name]').fill('Furina');page.locator('[data-wish-target-artwork="0"] img').evaluate("img=>{img.src='/missing-target-art.png'}");expect(page.locator('[data-wish-target-artwork="0"] img')).to_have_count(0);expect(page.locator('[data-wish-target-artwork="0"] .wish-target-art-placeholder')).to_be_visible()
   page.locator('[data-add]').click();page.locator('[data-target="1"][data-field=name]').fill('Clé de Khaj-Nisut');expect(page.locator('[data-wish-target-artwork="1"] img')).to_have_attribute('src','/assets/genshin/weapons/types/sword.png');expect(page.locator('[data-wish-target-artwork="1"]')).to_contain_text('Arme trouvée')
   page.set_viewport_size({'width':390,'height':844});page.evaluate("()=>{for(const href of ['/styles/planner.css','/styles/site-polish.css']){const link=document.createElement('link');link.rel='stylesheet';link.href=href;document.head.append(link)}}");page.wait_for_timeout(250);assert page.locator('.ordered-targets').evaluate('(node)=>node.scrollWidth<=node.clientWidth'), 'Les objectifs de vœux débordent sur téléphone'
   assert not errors,errors
   browser.close();print('Objectifs : copies et constellations synchronisées, synthèse et persistance validées.',flush=True)
 finally:server.shutdown();server.server_close()
if __name__=='__main__':main()
